CREATE TABLE "library_books" ("id" UUID NOT NULL DEFAULT uuidv7(),"school_id" UUID NOT NULL,"isbn" TEXT,"title" TEXT NOT NULL,"author" TEXT NOT NULL,"stock" INTEGER NOT NULL,"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "library_books_pkey" PRIMARY KEY("id"),CONSTRAINT "library_books_school_id_fkey" FOREIGN KEY("school_id") REFERENCES "schools"("id") ON DELETE CASCADE ON UPDATE CASCADE);CREATE UNIQUE INDEX "library_books_school_id_isbn_key" ON "library_books"("school_id","isbn");
CREATE TABLE "library_loans" ("id" UUID NOT NULL DEFAULT uuidv7(),"school_id" UUID NOT NULL,"book_id" UUID NOT NULL,"enrollment_id" UUID NOT NULL,"borrowed_at" DATE NOT NULL DEFAULT CURRENT_TIMESTAMP,"due_at" DATE NOT NULL,"returned_at" DATE,CONSTRAINT "library_loans_pkey" PRIMARY KEY("id"),CONSTRAINT "library_loans_school_id_fkey" FOREIGN KEY("school_id") REFERENCES "schools"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "library_loans_book_id_fkey" FOREIGN KEY("book_id") REFERENCES "library_books"("id") ON DELETE RESTRICT ON UPDATE CASCADE);CREATE INDEX "library_loans_school_id_enrollment_id_due_at_idx" ON "library_loans"("school_id","enrollment_id","due_at");
CREATE TABLE "canteen_meals" ("id" UUID NOT NULL DEFAULT uuidv7(),"school_id" UUID NOT NULL,"date" DATE NOT NULL,"menu" TEXT NOT NULL,"planned" INTEGER NOT NULL,"served" INTEGER NOT NULL,CONSTRAINT "canteen_meals_pkey" PRIMARY KEY("id"),CONSTRAINT "canteen_meals_school_id_fkey" FOREIGN KEY("school_id") REFERENCES "schools"("id") ON DELETE CASCADE ON UPDATE CASCADE);CREATE UNIQUE INDEX "canteen_meals_school_id_date_key" ON "canteen_meals"("school_id","date");
CREATE TABLE "transport_routes" ("id" UUID NOT NULL DEFAULT uuidv7(),"school_id" UUID NOT NULL,"name" TEXT NOT NULL,"vehicle" TEXT NOT NULL,"driver" TEXT NOT NULL,"capacity" INTEGER NOT NULL,"enrolled" INTEGER NOT NULL DEFAULT 0,"stops" JSONB NOT NULL,"status" "reference_status" NOT NULL DEFAULT 'ACTIVE',CONSTRAINT "transport_routes_pkey" PRIMARY KEY("id"),CONSTRAINT "transport_routes_school_id_fkey" FOREIGN KEY("school_id") REFERENCES "schools"("id") ON DELETE CASCADE ON UPDATE CASCADE);CREATE UNIQUE INDEX "transport_routes_school_id_name_key" ON "transport_routes"("school_id","name");
CREATE TABLE "inventory_items" ("id" UUID NOT NULL DEFAULT uuidv7(),"school_id" UUID NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"unit" TEXT NOT NULL,"quantity" DECIMAL(14,2) NOT NULL DEFAULT 0,"reorder_level" DECIMAL(14,2) NOT NULL DEFAULT 0,CONSTRAINT "inventory_items_pkey" PRIMARY KEY("id"),CONSTRAINT "inventory_items_school_id_fkey" FOREIGN KEY("school_id") REFERENCES "schools"("id") ON DELETE CASCADE ON UPDATE CASCADE);CREATE UNIQUE INDEX "inventory_items_school_id_code_key" ON "inventory_items"("school_id","code");
CREATE TABLE "inventory_movements" ("id" UUID NOT NULL DEFAULT uuidv7(),"school_id" UUID NOT NULL,"item_id" UUID NOT NULL,"quantity" DECIMAL(14,2) NOT NULL,"reason" TEXT NOT NULL,"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "inventory_movements_pkey" PRIMARY KEY("id"),CONSTRAINT "inventory_movements_school_id_fkey" FOREIGN KEY("school_id") REFERENCES "schools"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "inventory_movements_item_id_fkey" FOREIGN KEY("item_id") REFERENCES "inventory_items"("id") ON DELETE CASCADE ON UPDATE CASCADE);CREATE INDEX "inventory_movements_school_id_item_id_created_at_idx" ON "inventory_movements"("school_id","item_id","created_at");
